{
  "years_of_experience": {
    "type": "number",
    "description": "Total number of years of explicitly documented professional work experience. Count only employment, internships, or freelance work when clearly documented as professional experience. Do not count university study, academic projects, personal projects, diplomas, or courses. If no professional experience is explicitly documented, return 0. Never estimate or invent experience."
  },
  "education": {
    "type": "array",
    "description": "List of academic degrees, universities, diplomas, and relevant educational programs explicitly mentioned in the CV. Include ongoing programs and clearly identify their status.",
    "items": {
      "type": "object",
      "properties": {
        "institution": {
          "type": "string"
        },
        "degree_or_program": {
          "type": "string"
        },
        "field": {
          "type": "string"
        },
        "duration": {
          "type": "string"
        },
        "status": {
          "type": "string",
          "enum": [
            "Graduated",
            "In Progress",
            "Not Specified"
          ],
          "description": "Graduated only when completion is explicitly stated. In Progress when the candidate is currently enrolled. Not Specified when the CV does not clarify the status."
        }
      },
      "required": [
        "institution",
        "degree_or_program",
        "field",
        "duration",
        "status"
      ]
    }
  },
  "skills": {
    "type": "array",
    "description": "Technical skills explicitly mentioned or clearly demonstrated in the CV, including programming languages, frameworks, tools, concepts, and technologies. Do not add skills based only on job requirements or assumptions.",
    "items": {
      "type": "string"
    }
  },
  "certificates": {
    "type": "array",
    "description": "Professional certificates and completed certifications explicitly mentioned in the CV. Do not classify university degrees, ongoing diplomas, academic programs, or ordinary courses as professional certificates. Include only completed certifications. Return an empty array if none are explicitly mentioned.",
    "items": {
      "type": "string"
    }
  }
}

parameters.jsCode:
const results = [];
const norm = v => String(v ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const decide = s => (s >= 70 ? 'interview' : s >= 50 ? 'maybe' : 'reject');
const isStrArr = a => Array.isArray(a) && a.every(x => typeof x === 'string');

for (const item of $input.all()) {
  let ai = item.json.output ?? item.json;
  if (typeof ai === 'string') {
    try { ai = JSON.parse(ai); } catch (e) { ai = {}; }
  }

  const row = $('Get row(s) in sheet').item.json;
  const prep = $('Prepare Application').item.json;
  const errors = [];
  const warnings = [];

  // 1. Required fields
  const required = ['score', 'recommendation', 'matched_requirements', 'missing_requirements', 'strengths', 'concerns', 'interview_questions', 'topSkills'];
  for (const f of required) {
    if (ai[f] === undefined || ai[f] === null) errors.push(`Missing field: ${f}`);
  }

  // 2. Field types
  for (const f of ['strengths', 'concerns', 'topSkills']) {
    if (ai[f] != null && typeof ai[f] !== 'string') errors.push(`Field ${f} must be a string`);
  }
  for (const f of ['matched_requirements', 'missing_requirements', 'interview_questions']) {
    if (ai[f] != null && !isStrArr(ai[f])) errors.push(`Field ${f} must be an array of strings`);
  }
  if (Array.isArray(ai.interview_questions) && ai.interview_questions.length !== 3) {
    errors.push(`Expected 3 interview questions, got ${ai.interview_questions.length}`);
  }

  // 3. Score
  const score = ai.score;
  const scoreOk = typeof score === 'number' && Number.isInteger(score) && score >= 0 && score <= 100;
  if (!scoreOk) errors.push('Score must be an integer between 0 and 100');

  // 4. Recommendation
  const allowed = ['interview', 'maybe', 'reject'];
  const aiRec = norm(ai.recommendation);
  if (ai.recommendation != null && !allowed.includes(aiRec)) {
    errors.push('Recommendation must be interview, maybe or reject');
  } else if (scoreOk && aiRec && aiRec !== decide(score)) {
    warnings.push(`AI recommendation (${aiRec}) did not match score ${score}, corrected to ${decide(score)}`);
  }

  // 5. Soft checks (warnings only)
  if (ai.name && norm(ai.name) !== norm(row.name)) warnings.push('AI candidate name differs from the submitted name');
  if (ai.yearsExperience != null && (typeof ai.yearsExperience !== 'number' || ai.yearsExperience < 0)) warnings.push('yearsExperience is not a valid number');
  if (typeof ai.strengths === 'string' && ai.strengths.trim().length < 20) warnings.push('Strengths text is too short');

  const valid = errors.length === 0;
  const years = typeof ai.yearsExperience === 'number' && ai.yearsExperience >= 0 ? ai.yearsExperience : null;

  results.push({
    json: {
      appliedAt: row['apllied at?'] ?? '',
      name: row.name ?? '',
      email: row.email ?? '',
      position: row.position ?? '',
      motivation: row.motivation ?? '',
      readMethod: prep.readMethod ?? '',
      cvFileId: row['cv file id'] ?? '',
      score: scoreOk ? score : null,
      recommendation: valid ? decide(score) : 'error',
      matched_requirements: isStrArr(ai.matched_requirements) ? ai.matched_requirements : [],
      missing_requirements: isStrArr(ai.missing_requirements) ? ai.missing_requirements : [],
      strengths: typeof ai.strengths === 'string' ? ai.strengths : '',
      concerns: typeof ai.concerns === 'string' ? ai.concerns : '',
      interview_questions: isStrArr(ai.interview_questions) ? ai.interview_questions : [],
      yearsExperience: years,
      topSkills: typeof ai.topSkills === 'string' ? ai.topSkills : '',
      valid,
      problems: [...errors, ...warnings].join(' | ')
    }
  });
}

return results;
